"""Canonical, content-backed living Markdown layout and conservative migrations."""
from __future__ import annotations
import argparse
import json
from pathlib import Path, PurePosixPath
import re
import shutil
from urllib.parse import quote, unquote

FOOTER = 'GENERATED BY AIKYA HARNESS'
LEGACY = ('<!-- GENERATED BY AIKYA SDD 6.1.1 -->',
          '<!-- GENERATED BY AIKYA SDD 6.0.0 -->','<!-- GENERATED BY CLAUDE-DEV-HARNESS -->',
          '<!-- GENERATED BY AIKYA-HARNESS -->',
          '<!-- GENERATED BY AIKYA-HARNESS: skills-registry -->',
          '<!-- GENERATED BY AIKYA-HARNESS: engineering-catalog -->',
          '<!-- GENERATED BY AIKYA-HARNESS: engineering-agents -->')
PATHS = {'agents.md':'tools/agents.md',
         'harness/token-policy.md':'tools/token-policy.md',
         'quality/testing.md':'plan/testing.md',
         'architecture/overview.md':'architecture/architecture-overview.md',
         'architecture/03.-arquitectura.md':'architecture/architecture-overview.md',
         'bugs/index.md':'bugs/bugs.md',
         'infrastructure/architecture.md':'architecture/infrastructure.md'}
ABSORB = ('harness/bootstrap.md','harness/requirements.md','harness/installer-readme.md')
RETIRE = ('harness/skills-comparison.md','harness/skill-comparison.md')


def content(body: str) -> str:
    lines=body.strip().splitlines()
    while lines and lines[0].strip().startswith('<!-- GENERATED BY '): lines.pop(0)
    while lines and lines[-1].strip()==FOOTER: lines.pop()
    return '\n'.join(lines).strip()


def generated(body: str) -> bool:
    return body.rstrip().endswith(FOOTER) or body.lstrip().startswith(LEGACY)


def stamp(body: str) -> str:
    return content(body)+'\n\n'+FOOTER+'\n'


def asset_bytes(relative: str | Path, raw: bytes, *, suffix: str='') -> bytes:
    """Finish first-party Markdown artifacts without altering code or config bytes."""
    if Path(relative).suffix.lower() != '.md':
        return raw+suffix.encode('utf8')
    body=content(raw.decode('utf8'))
    if suffix:body+='\n'+suffix
    return stamp(body).encode('utf8')


def substantive(body: str) -> bool:
    return any(line.strip() and not line.lstrip().startswith(('#','<!--','|---'))
               and line.strip() not in (FOOTER,'---','TODO','TBD','Pending','Pendiente')
               for line in content(body).splitlines())


def canonical(relative: str) -> str:
    if not isinstance(relative,str) or '\\' in relative: raise ValueError('Invalid documentation path')
    if relative.startswith('aikya/docs/'): relative=relative[len('aikya/docs/'):]
    parts=relative.split('/')
    if not parts or any(p in ('','.', '..') for p in parts) or PurePosixPath(relative).is_absolute():
        raise ValueError('Documentation paths must be relative and contained')
    if not relative.lower().endswith('.md'): raise ValueError('Only Markdown documents are supported')
    if parts[0].lower() in ('plans','plan'):parts[0]='plan'
    if parts[0].lower() in ('bug','bugs'):parts[0]='bugs'
    if parts[-1].lower() in ('03.-arquitectura.md','03.-architecture.md','architecture-overview.md'):
        return 'architecture/architecture-overview.md'
    if parts[0].lower().startswith(('feature-', 'feature_')):
        parts=['features']+[p.lower() for p in parts]
    elif parts[0].lower()=='features': parts=[p.lower() for p in parts]
    relative='/'.join(parts)
    return PATHS.get(relative,relative)


def _managed_runtime_asset(root:Path,name:str,body:str)->bool:
    """Recognize installed reference material by its ownership manifest and bytes."""
    import hashlib
    for prefix in ('aikya/scripts/harness/','.aikya/runtime/'):
        if not name.startswith(prefix):continue
        manifest=root/prefix/'.bundle-manifest.json'
        if manifest.is_symlink() or not manifest.is_file() or manifest.stat().st_size>3_000_000:return False
        try:
            data=json.loads(manifest.read_text(encoding='utf8'))
            expected=data.get('files',{}).get(name.removeprefix(prefix))
            return expected==hashlib.sha256(body.encode('utf8')).hexdigest()
        except (ValueError,OSError,AttributeError,TypeError):return False
    return False


def validate_generated_document_paths(root:Path,paths:list[str])->list[str]:
    """Inspect only candidate Markdown, preserving unmarked project documentation."""
    root=Path(root).absolute();errors=[]
    contracts={'README.md','README.es.md','CHANGELOG.md','CLAUDE.md','AGENTS.md',
               'SECURITY.md','CONTRIBUTING.md','CODE_OF_CONDUCT.md','THIRD_PARTY_LICENSES.md',
               '.aikya/analysis/report.md'}
    assets=('.claude/','.github/','template/','engineering/','aikya-skills/',
            'sdd-templates/','claude-templates/','aikya-template/',
            'src/aikya/resources/','tests/fixtures/','examples/')
    for name in sorted(set(paths)):
        if not isinstance(name,str) or not name.lower().endswith('.md'):continue
        parts=name.split('/')
        if name.startswith('/') or '\\' in name or any(p in ('','.','..') for p in parts):
            errors.append('Unsafe documentation candidate: '+name);continue
        path=root/name
        if any(p.is_symlink() for p in (path,*path.parents) if p==root or root in p.parents):
            errors.append('Symlinked documentation candidate: '+name);continue
        if not path.exists():continue
        if not path.is_file() or path.stat().st_size>3_000_000:
            errors.append('Documentation candidate requires review: '+name);continue
        try:body=path.read_text(encoding='utf8')
        except (UnicodeError,OSError):
            errors.append('Unreadable documentation candidate: '+name);continue
        if not generated(body) or name in contracts or name.startswith(assets):continue
        if _managed_runtime_asset(root,name,body):continue
        if Path(name).name in ('README.md','README.es.md') and parts[0] in ('apps','packages','contracts','infra'):continue
        if not name.startswith('aikya/docs/'):
            errors.append('Generated plans, bugs, features and reports must be inside aikya/docs/: '+name)
    return errors


def safe(root: Path, relative: str) -> Path:
    path=root/'aikya/docs'/relative
    for part in (path,*path.parents):
        if part==root.parent: break
        if part.is_symlink(): raise ValueError('Symlinked documentation path: '+str(part))
    if not path.resolve().is_relative_to(root.resolve()): raise ValueError('Documentation path escapes project')
    return path


def _write(path: Path, body: str) -> None:
    from aikya.storage import atomic_write
    atomic_write(path,body)


def index_paths(root: Path) -> list[str]:
    """Validate index ownership and the complete inventory before document writes."""
    root=Path(root).absolute();base=safe(root,'indice.md').parent
    target=safe(root,'indice.md')
    if target.exists() and not generated(target.read_text(encoding='utf8')):
        raise ValueError('Customized indice.md must be reviewed, not replaced')
    paths=[]
    if base.exists():
        if not base.is_dir():raise ValueError('Documentation root is not a directory')
        for file in sorted(base.rglob('*.md')):
            relative=file.relative_to(base).as_posix()
            safe(root,relative)
            if file.is_file():paths.append(relative)
    if 'indice.md' not in paths:paths.append('indice.md')
    return sorted(paths)


def update_index(root: Path, language: str|None=None) -> None:
    from aikya.documentation.language import resolve
    root=Path(root).absolute();paths=index_paths(root)
    target=safe(root,'indice.md')
    if not target.parent.exists():return
    title='Índice de documentos' if (language or resolve(root))=='es' else 'Document index'
    body='# '+title+'\n\n'+'\n'.join('- ['+p+']('+quote(p,safe='/.-_')+')' for p in paths)+'\n'
    _write(target,stamp(body))


def write_document(root: Path, relative: str, body: str, *, replace_generated: bool=False, index: bool=True) -> str|None:
    root=Path(root).absolute();relative=canonical(relative)
    if not substantive(body): return None
    if relative.startswith('harness/') or (relative.startswith('tools/') and relative not in ('tools/agents.md','tools/token-policy.md','tools/skill-comparison.md')):
        raise ValueError('Unsupported tools document: '+relative)
    target=safe(root,relative);value=stamp(body)
    if target.exists() and target.read_text(encoding='utf8')!=value:
        if not replace_generated or not generated(target.read_text(encoding='utf8')):
            raise ValueError('Customized or existing document requires review: '+relative)
    if index:index_paths(root)
    if not target.exists() or target.read_text(encoding='utf8')!=value:_write(target,value)
    if index:update_index(root)
    return 'aikya/docs/'+relative


def remap_links(body: str, source: str, destination: str, available: set|None=None, *, asset_prefix: str='') -> str:
    import posixpath
    def replace(match):
        label, link=match.group(1),match.group(2)
        if re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:',link) or link.startswith('#'):return match.group(0)
        path,separator,anchor=link.partition('#')
        path=unquote(path)
        resolved=posixpath.normpath(posixpath.join(posixpath.dirname(source),path))
        if resolved.startswith('/'):return match.group(0)
        inside=resolved!='..' and not resolved.startswith('../')
        is_md=inside and resolved.lower().endswith('.md')
        mapped=('overview.md' if resolved in ABSORB else canonical(resolved)) if is_md else posixpath.join(asset_prefix,resolved)
        if is_md and available is not None and mapped not in available:return label
        return '['+label+']('+quote(posixpath.relpath(mapped,posixpath.dirname(destination) or '.'),safe='/.-_')+(separator+anchor if separator else '')+')'
    return re.sub(r'\[([^\]]+)\]\(([^)]+)\)',replace,body)


def template_pages(profile: dict, modules: list[dict], raw: dict[str,str], language: str) -> dict[str,str]:
    """Do not scaffold reports when no facts or actual decision records back them."""
    existing=profile.get('mode')=='existing';result={}
    for name,body in raw.items():
        rel=name.removeprefix('aikya/docs/')
        if rel in RETIRE or rel in ('features/index.md','bugs/index.md','bugs/bugs.md','design/design-system.md'):continue
        if existing:
            if rel in ('plan/roadmap.md','decisions/README.md','decisions/0001-entrevista-stack.md'):continue
            if rel=='quality/testing.md':
                evidence=profile.get('_documentation_testing_evidence')
                if not evidence:continue
                title='Evidencia de pruebas observada' if language=='es' else 'Observed testing evidence'
                note='Rutas observadas; las pruebas no se han ejecutado ni validado.' if language=='es' else 'Observed paths only; tests have not been executed or validated.'
                body='# '+title+'\n\n'+note+'\n\n'+'\n'.join('- `'+p+'`' for p in evidence)
        if rel=='security/security.md' and profile.get('auth') in (None,'none','undecided'):continue
        if rel=='operations/observability.md' and profile.get('observability') in (None,'none','undecided'):continue
        if rel=='operations/deployment.md' and all(profile.get(k) in (None,'none','undecided') for k in ('ci','deployment')):continue
        if canonical(rel)=='architecture/architecture-overview.md':
            from aikya.documentation.templates import architecture_snapshot
            body=architecture_snapshot(profile,modules,language)
        from aikya.documentation.composition import bootstrap
        body=bootstrap(canonical(rel),body,profile,modules,language)
        if substantive(body):result['aikya/docs/'+canonical(rel)]=stamp(body)
    available={name.removeprefix('aikya/docs/') for name in result}
    for name,body in list(result.items()):
        relative=name.removeprefix('aikya/docs/')
        result[name]=remap_links(body,relative,relative,available)
    # Navigation lists only planned documents. indice.md inventories actual files later.
    title='Documentación viva' if language=='es' else 'Living documentation'
    intro='Documentos con datos registrados; no implican verificaciones ni despliegues.' if language=='es' else 'Recorded project documentation; files do not prove verification or deployment.'
    links=['- ['+p.removeprefix('aikya/docs/')+']('+quote(p.removeprefix('aikya/docs/'),safe='/.-_')+')' for p in sorted(result) if not p.endswith('/README.md')]
    result['aikya/docs/README.md']=stamp('# '+title+' — '+str(profile.get('name','Project'))+'\n\n'+intro+'\n\n- [indice.md](indice.md)\n'+'\n'.join(links))
    return result


def append_section(root: Path, relative: str, title: str, body: str) -> None:
    path=safe(root,canonical(relative));old=path.read_text(encoding='utf8') if path.exists() else '# '+title+'\n'
    if path.exists() and not generated(old):raise ValueError('Customized document requires review: '+relative)
    heading='## '+title
    text=content(old)
    pattern=r'(?ms)^'+re.escape(heading)+r'\n.*?(?=^## |\Z)'
    section=heading+'\n\n'+content(body)+'\n\n'
    updated=re.sub(pattern,lambda m:section,text,count=1) if re.search(pattern,text) else text+'\n\n'+section
    write_document(root,relative,updated,replace_generated=True)


def migration_plan(root: Path) -> list[dict]:
    root=Path(root).absolute();base=safe(root,'indice.md').parent
    if not base.exists():return []
    operations=[]
    index=safe(root,'indice.md')
    if index.exists() and not generated(index.read_text(encoding='utf8')):
        return [{'source':'indice.md','target':'indice.md','action':'BLOCKED','reason':'Customized index preserved'}]
    for source in sorted(base.rglob('*.md')):
        rel=source.relative_to(base).as_posix();safe(root,rel)
        text=source.read_text(encoding='utf8')
        dest=canonical(rel)
        if rel in ABSORB or rel in RETIRE: action='ABSORB_OVERVIEW' if rel in ABSORB else 'RETIRE_UNREQUESTED_COMPARISON'
        elif dest!=rel:action='MOVE'
        elif rel.startswith('harness/'):
            operations.append({'source':rel,'target':dest,'action':'BLOCKED','reason':'Unrecognized legacy tools document requires review'});continue
        elif generated(text) and stamp(remap_links(text,rel,rel))!=text:action='FOOTER'
        else:continue
        if not generated(text):
            operations.append({'source':rel,'target':dest,'action':'BLOCKED','reason':'Customized document preserved'});continue
        if action=='MOVE':
            target=safe(root,dest)
            if target.exists() and not source.samefile(target) and content(target.read_text(encoding='utf8'))!=content(text):
                operations.append({'source':rel,'target':dest,'action':'BLOCKED','reason':'Destination contains different content'});continue
        if action=='ABSORB_OVERVIEW':
            target=safe(root,'overview.md')
            if target.exists() and not generated(target.read_text(encoding='utf8')):
                operations.append({'source':rel,'target':'overview.md','action':'BLOCKED','reason':'Customized overview preserved'});continue
            dest='overview.md'
        operations.append({'source':rel,'target':dest,'action':action})
    targets={}
    for op in operations:
        if op['action']=='MOVE':
            previous=targets.get(op['target'])
            if previous and content(safe(root,previous['source']).read_text(encoding='utf8'))!=content(safe(root,op['source']).read_text(encoding='utf8')):
                op.update(action='BLOCKED',reason='Multiple documents target the same canonical path')
                previous.update(action='BLOCKED',reason='Multiple documents target the same canonical path')
            targets[op['target']]=op
    return operations


def migrate(root: Path, *, approved: bool=False) -> list[dict]:
    root=Path(root).absolute();operations=migration_plan(root)
    if not approved:return operations
    if any(op['action']=='BLOCKED' for op in operations):raise ValueError('Documentation migration requires review: '+json.dumps(operations))
    prepared=[]
    for op in operations:
        source=safe(root,op['source']);text=source.read_text(encoding='utf8')
        rewritten=stamp(remap_links(text,op['source'],op['target']))
        backup=root/'.harness/backup-docs-layout'/op['source']
        for part in (backup,*backup.parents):
            if part==root.parent:break
            if part.is_symlink():raise ValueError('Symlinked documentation backup')
        prepared.append((op,source,text,rewritten,backup))
    # Rewrite stationary pages before appending migrated sections to overview.
    prepared.sort(key=lambda item: item[0]['action']!='FOOTER')
    for op,source,text,rewritten,backup in prepared:
        backup.parent.mkdir(parents=True,exist_ok=True)
        if not backup.exists():shutil.copy2(source,backup)
        if op['action']=='MOVE':
            target=safe(root,op['target']);target.parent.mkdir(parents=True,exist_ok=True)
            if not target.exists() or source.samefile(target):source.rename(target)
            else:source.unlink()
            _write(target,rewritten)
        elif op['action']=='FOOTER':_write(source,rewritten)
        elif op['action']=='ABSORB_OVERVIEW':
            append_section(root,'overview.md',{'harness/bootstrap.md':'Project initialization','harness/requirements.md':'Recorded toolchain diagnostics','harness/installer-readme.md':'Recorded installation guidance'}[op['source']],remap_links(text,op['source'],'overview.md'))
            source.unlink()
        elif op['action']=='RETIRE_UNREQUESTED_COMPARISON':source.unlink()
    base=root/'aikya/docs'
    if base.exists():
        for directory in sorted((p for p in base.rglob('*') if p.is_dir() and not p.is_symlink()),key=lambda p:len(p.parts),reverse=True):
            try:directory.rmdir()
            except OSError:pass
        update_index(root)
    return operations


def record_skill_comparison(root: Path, record: dict) -> None:
    entries=record.get('skills',{})
    if not isinstance(entries,dict) or not entries:return
    from aikya.documentation.language import resolve
    title='Comparación de skills' if resolve(root)=='es' else 'Skill installation comparison'
    safe_cell=lambda v:str(v).replace('|','/').replace('\n',' ').replace('\r',' ')[:700]
    rows=['| Skill | Result | Source | Version / commit |','|---|---|---|---|']
    for name,item in sorted(entries.items()):
        rows.append('| '+' | '.join(safe_cell(v) for v in (name,item.get('state','unknown'),item.get('source') or record.get('sources',{}).get(name,''),item.get('commit') or item.get('version') or 'Not recorded'))+' |')
    write_document(root,'tools/skill-comparison.md','# '+title+'\n\n'+'\n'.join(rows),replace_generated=True)


def validate_layout(root: Path) -> list[str]:
    errors=[];base=Path(root)/'aikya/docs'
    if not base.exists():return errors
    actual=[]
    for path in sorted(base.rglob('*.md')):
        relative=path.relative_to(base).as_posix()
        try:
            safe(root,relative)
            if canonical(relative)!=relative:errors.append('Noncanonical documentation path: '+relative)
            if relative.startswith('harness/'):errors.append('Legacy documentation harness directory: '+relative)
            if relative.startswith('tools/') and relative not in ('tools/agents.md','tools/token-policy.md','tools/skill-comparison.md'):
                errors.append('Unexpected tools document: '+relative)
            actual.append(relative)
        except ValueError as exc:errors.append(str(exc))
    index=base/'indice.md'
    if index.is_file() and not index.is_symlink():
        from urllib.parse import unquote
        indexed={unquote(x) for x in re.findall(r'\[[^\]]+\]\(([^)]+)\)',index.read_text(encoding='utf8'))}
        if set(actual)!=indexed:errors.append('indice.md must list exactly the existing Markdown paths; refresh the index after approved writes')
    else:errors.append('Missing indice.md')
    return errors


def main(argv=None):
    p=argparse.ArgumentParser(description='Write canonical Aikya documentation and index actual Markdown')
    p.add_argument('action',choices=['write','index','normalize'])
    p.add_argument('--root',type=Path,default=Path.cwd());p.add_argument('--path');p.add_argument('--input',type=Path);p.add_argument('--approved',action='store_true')
    a=p.parse_args(argv)
    try:
        if a.action=='write':
            if not a.approved or not a.path or not a.input:raise ValueError('Writing requires --approved, --path and --input')
            print(write_document(a.root,a.path,a.input.read_text(encoding='utf8'),replace_generated=True))
        elif a.action=='index':
            if not a.approved:raise ValueError('Index updates require --approved')
            update_index(a.root)
        else:print(json.dumps(migrate(a.root,approved=a.approved),indent=2))
        return 0
    except (OSError,ValueError,UnicodeError) as exc:print('ERROR:',exc);return 2

if __name__=='__main__':raise SystemExit(main())
